package com.fixflow.mall.api;

import com.fixflow.mall.domain.MallOrder;
import com.fixflow.mall.service.OrderService;
import com.fixflow.mall.service.UserService;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
@DisplayName("MallController 单元测试")
class MallControllerTest {

    @Mock
    private UserService userService;

    @Mock
    private OrderService orderService;

    @InjectMocks
    private MallController mallController;

    @Test
    @DisplayName("正向测试：验证修复后的 getOrder 方法在正常输入下能正确工作")
    void testGetOrderWithValidOrderId() {
        // 准备测试数据
        Long orderId = 1L;
        MallOrder expectedOrder = new MallOrder();
        expectedOrder.setId(orderId);
        expectedOrder.setOrderNumber("ORD-001");

        // 设置 Mock 行为
        when(orderService.findOrder(orderId)).thenReturn(expectedOrder);

        // 执行测试
        MallOrder actualOrder = mallController.getOrder(orderId);

        // 验证结果
        assertEquals(expectedOrder, actualOrder);
    }

    @Test
    @DisplayName("边界测试：验证原来导致异常的输入现在不再抛出异常")
    void testGetOrderWithPathVariableMismatchFixed() {
        // 这个测试验证修复前会导致 MissingPathVariableException 的输入现在能正常工作
        // 修复前: @PathVariable("id") Long orderId 与路径变量 {orderId} 不匹配
        // 修复后: @PathVariable("orderId") Long orderId 与路径变量 {orderId} 匹配

        // 准备测试数据
        Long orderId = 2L;
        MallOrder expectedOrder = new MallOrder();
        expectedOrder.setId(orderId);

        // 设置 Mock 行为
        when(orderService.findOrder(orderId)).thenReturn(expectedOrder);

        // 执行测试 - 应该不再抛出 MissingPathVariableException
        MallOrder actualOrder = mallController.getOrder(orderId);

        // 验证结果
        assertEquals(expectedOrder, actualOrder);
    }

    @Test
    @DisplayName("验证修复后的空值/null 处理")
    void testGetOrderWithNullOrderId() {
        // 准备测试数据
        Long orderId = null;

        // 设置 Mock 行为
        when(orderService.findOrder(orderId)).thenReturn(null);

        // 执行测试
        MallOrder actualOrder = mallController.getOrder(orderId);

        // 验证结果
        assertNull(actualOrder);
    }

    @Test
    @DisplayName("正向测试：验证 nickname 方法在正常输入下能正确工作")
    void testNicknameWithValidUserId() {
        // 准备测试数据
        Long userId = 1L;
        String expectedNickname = "TestUser";

        // 设置 Mock 行为
        when(userService.getNickname(userId)).thenReturn(expectedNickname);

        // 执行测试
        String actualNickname = mallController.nickname(userId);

        // 验证结果
        assertEquals(expectedNickname, actualNickname);
    }

    @Test
    @DisplayName("正向测试：验证 firstItem 方法在正常输入下能正确工作")
    void testFirstItemWithValidOrderId() {
        // 准备测试数据
        Long orderId = 1L;
        Long expectedItemId = 101L;

        // 设置 Mock 行为
        when(orderService.firstItemId(orderId)).thenReturn(expectedItemId);

        // 执行测试
        Long actualItemId = mallController.firstItem(orderId);

        // 验证结果
        assertEquals(expectedItemId, actualItemId);
    }
}
